#include <stdio.h>
#include <stdlib.h>

void leak() {
    int *p = (int*)malloc(sizeof(int));
    *p = 10;
    // free(p); // 까먹음!
}
// 함수가 끝나면 p 변수(스택)는 사라지지만,
// 힙에 할당된 4바이트는 영원히 남아있습니다.

int main() {
    for(int i=0; i<3; i++) {
        leak();
        printf("Memory leaked %d times\n", i+1);
    }
    return 0;
}
